const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to our local history centre and heritage park.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.386458333333334},{"speaker":"A","text":"Before you explore the main building today I would like to share some useful visitor information.","position":2,"audioStartSeconds":4.586458333333334,"audioEndSeconds":10.192125},{"speaker":"A","text":"We are open from Tuesday until Sunday every week throughout the year.","position":3,"audioStartSeconds":10.392125,"audioEndSeconds":14.825875},{"speaker":"A","text":"Please note that we remain completely closed on every Monday for weekly maintenance work.","position":4,"audioStartSeconds":15.025875,"audioEndSeconds":20.708083333333335},{"speaker":"A","text":"Our morning opening time is nine o clock so you can arrive early.","position":5,"audioStartSeconds":20.908083333333334,"audioEndSeconds":24.890833333333333},{"speaker":"A","text":"In the afternoon the centre closes sharply at five o clock to allow our staff to leave.","position":6,"audioStartSeconds":25.090833333333332,"audioEndSeconds":30.567625},{"speaker":"A","text":"General admission is completely free for all individual visitors and local residents.","position":7,"audioStartSeconds":30.767625,"audioEndSeconds":36.514291666666665},{"speaker":"A","text":"However we do ask for a small donation of three pounds if you join a guided tour.","position":8,"audioStartSeconds":36.71429166666667,"audioEndSeconds":41.80525},{"speaker":"A","text":"If you walk behind the main exhibition hall you will discover our wonderful heritage garden.","position":9,"audioStartSeconds":42.00525,"audioEndSeconds":47.559375},{"speaker":"A","text":"Visitors can also enjoy hot drinks and snacks at our sunny courtyard cafe.","position":10,"audioStartSeconds":47.759375,"audioEndSeconds":53.03},{"speaker":"A","text":"Our souvenir gift shop sells wonderful books and traditional handmade crafts made by local artists.","position":11,"audioStartSeconds":53.23,"audioEndSeconds":59.686166666666665},{"speaker":"A","text":"Large backpacks and heavy umbrellas must be left inside the secure cloakroom near the entrance.","position":12,"audioStartSeconds":59.88616666666667,"audioEndSeconds":65.90420833333333},{"speaker":"A","text":"Photography without flash is permitted inside the galleries but video recording is strictly prohibited everywhere.","position":13,"audioStartSeconds":66.10420833333333,"audioEndSeconds":73.063},{"speaker":"A","text":"If you need any extra assistance during your visit please speak with our friendly staff at the main reception desk.","position":14,"audioStartSeconds":73.263,"audioEndSeconds":80.06979166666666}],"questions":[{"prompt":"Weekly closure day: ______","answer":"Monday","evidenceSentence":4,"evidence":"Monday","explanation":"Hướng dẫn viên thông báo trung tâm đóng cửa vào thứ Hai hàng tuần để bảo trì."},{"prompt":"Afternoon closing time: ______","answer":"five o clock","evidenceSentence":6,"evidence":"five o clock","explanation":"Trung tâm đóng cửa vào lúc năm giờ chiều."},{"prompt":"Guided tour donation: ______ pounds","answer":"three","evidenceSentence":8,"evidence":"three pounds","explanation":"Có khoản quyên góp nhỏ là ba bảng nếu tham gia tour có hướng dẫn."},{"prompt":"On-site cafe location: ______ courtyard","answer":"sunny","evidenceSentence":10,"evidence":"sunny courtyard cafe","explanation":"Quán cà phê nằm ở khu sân trong đầy nắng."},{"prompt":"Items left in the cloakroom: ______ and umbrellas","answer":"backpacks","evidenceSentence":12,"evidence":"backpacks","explanation":"Ba lô lớn và ô nặng phải được gửi ở phòng giữ đồ."},{"prompt":"Prohibited inside the galleries: video ______","answer":"recording","evidenceSentence":13,"evidence":"video recording","explanation":"Việc quay phim bị cấm hoàn toàn trong các phòng trưng bày."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
